#include <LiquidCrystal.h>

// ==========================================
// SMART GREENHOUSE - PID TEMPERATURE CONTROL
// Arduino UNO + Proteus
// ==========================================

// LCD: RS, E, D4, D5, D6, D7
LiquidCrystal lcd(12, 11, 5, 4, 3, 2);

// Outputs
const byte HEATER_PIN = 9;
const byte FAN_PIN = 10;

// LM35 temperature sensor
const byte TEMP_SENSOR_PIN = A0;

// Desired temperature
double setpoint = 25.0;

// PID parameters: initial tuning values
double Kp = 35.0;
double Ki = 0.8;
double Kd = 2.0;

// PID variables
double integral = 0.0;
double previousError = 0.0;

// Control timing
const unsigned long CONTROL_INTERVAL = 100;
const unsigned long DISPLAY_INTERVAL = 500;

unsigned long previousControlTime = 0;
unsigned long previousDisplayTime = 0;

// Output values
int heaterPWM = 0;
int fanPWM = 0;

// Measured temperature
double temperature = 0.0;

// ==========================================
// Read temperature from LM35
// ==========================================

double readTemperature() {
  int sensorValue = analogRead(TEMP_SENSOR_PIN);

  // Arduino UNO ADC: 10-bit, reference approximately 5V
  double voltage = sensorValue * (5.0 / 1023.0);

  // LM35 output: 10mV per degree Celsius
  double tempC = voltage * 100.0;

  return tempC;
}

// ==========================================
// Setup
// ==========================================

void setup() {
  pinMode(HEATER_PIN, OUTPUT);
  pinMode(FAN_PIN, OUTPUT);

  analogWrite(HEATER_PIN, 0);
  analogWrite(FAN_PIN, 0);

  lcd.begin(16, 2);
  lcd.clear();

  lcd.setCursor(0, 0);
  lcd.print("Greenhouse PID");

  lcd.setCursor(0, 1);
  lcd.print("Starting...");

  delay(1500);
  lcd.clear();

  unsigned long now = millis();

  previousControlTime = now;
  previousDisplayTime = now;

  temperature = readTemperature();
}

// ==========================================
// Main loop
// ==========================================

void loop() {
  unsigned long now = millis();

  // ========================================
  // PID control
  // ========================================

  if (now - previousControlTime >= CONTROL_INTERVAL) {

    double dt =
        (now - previousControlTime) / 1000.0;

    previousControlTime = now;

    // Read actual sensor temperature
    temperature = readTemperature();

    // Calculate error
    double error = setpoint - temperature;

    // Integral term with anti-windup
    integral += error * dt;
    integral = constrain(integral, -100.0, 100.0);

    // Derivative term
    double derivative = 0.0;

    if (dt > 0.0) {
      derivative = (error - previousError) / dt;
    }

    previousError = error;

    // PID output
    double output =
        Kp * error +
        Ki * integral +
        Kd * derivative;

    // Limit output
    output = constrain(output, -255.0, 255.0);

    // ======================================
    // Heating or cooling
    // ======================================

    if (error > 0.2) {
      // Temperature is below setpoint
      heaterPWM = (int)max(0.0, output);
      fanPWM = 0;
    }
    else if (error < -0.2) {
      // Temperature is above setpoint
      heaterPWM = 0;
      fanPWM = (int)max(0.0, -output);
    }
    else {
      // Near setpoint
      heaterPWM = 0;
      fanPWM = 0;
      integral = 0.0;
    }

    // Apply PWM to outputs
    analogWrite(HEATER_PIN, heaterPWM);
    analogWrite(FAN_PIN, fanPWM);
  }

  // ========================================
  // LCD display
  // ========================================

  if (now - previousDisplayTime >= DISPLAY_INTERVAL) {

    previousDisplayTime = now;

    lcd.setCursor(0, 0);
    lcd.print("Temp:");
    lcd.print(temperature, 1);
    lcd.write(byte(223));
    lcd.print("C   ");

    lcd.setCursor(0, 1);

    if (heaterPWM > 0) {
      lcd.print("HEATING ");
      lcd.print(heaterPWM);
      lcd.print("   ");
    }
    else if (fanPWM > 0) {
      lcd.print("COOLING ");
      lcd.print(fanPWM);
      lcd.print("   ");
    }
    else {
      lcd.print("SETPOINT REACHED");
    }
  }
}
